/* Drumhead tuning: the ideal circular membrane model, a fixture generated by an
   independent Python reference (which finds the Bessel zeros from the power
   series itself), the catalog cases, the identities that follow from the wave
   equation, and the page contract. No expected number comes from the page. */
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const assert = require('node:assert/strict');

const root = path.resolve(__dirname, '..');
const slug = 'drumhead-tuning-calculator';
const html = fs.readFileSync(path.join(root, 'frontend/tools', slug, 'index.html'), 'utf8');
const startMarker = '/* drumhead-core:start */';
const endMarker = '/* drumhead-core:end */';
const start = html.indexOf(startMarker);
const end = html.indexOf(endMarker);
assert.ok(start > -1 && end > start, 'core markers missing');
const coreSource = html.slice(start, end + endMarker.length);
assert.ok(!/document\.|window\./.test(coreSource), 'the core stays free of DOM access');
const sandbox = { module: {} };
vm.createContext(sandbox);
vm.runInContext(coreSource + '\nmodule.exports = DrumheadCore;', sandbox);
const C = sandbox.module.exports;

const near = (actual, expected, label, relative) => {
  const rel = relative === undefined ? 1e-9 : relative;
  assert.ok(Number.isFinite(actual), label + ': ' + actual + ' is not a finite number');
  assert.ok(Math.abs(actual - expected) <= rel * Math.max(1, Math.abs(expected)),
    label + ': ' + actual + ' is not within ' + rel + ' of ' + expected);
};
const failure = (input) => {
  try { C.analyze(input); } catch (error) { return error.message; }
  return null;
};
const base = { mode: 'tension', unit: 'in', diameter: '14', density: '356', tension: '2000' };

// ---- Constants: the Bessel zeros the model turns on.
near(C.ALPHA.m01, 2.404825557695773, 'first zero of J0', 1e-14);
near(C.ALPHA.m11, 3.831705970207512, 'first zero of J1', 1e-14);
near(C.ALPHA.m21, 5.135622301840683, 'first zero of J2', 1e-14);
near(C.ALPHA.m02, 5.520078110286311, 'second zero of J0', 1e-14);
assert.equal(C.UNIT_MM.in, 25.4);
assert.equal(C.UNIT_MM.cm, 10);
assert.equal(C.UNIT_MM.mm, 1);
assert.equal(C.A4, 440);
assert.equal(C.LIMITS.tension[1], 50000);

// ---- Parsing and the exact user-facing messages.
assert.equal(failure({ ...base, diameter: '' }), 'Enter the head diameter.');
assert.equal(failure({ ...base, diameter: 'fourteen' }), 'Head diameter must be a number.');
assert.equal(failure({ ...base, diameter: '1.2e1' }), 'Head diameter must be a number.');
assert.equal(failure({ ...base, diameter: '-14' }), 'Head diameter must be between 2 and 40 inches.');
assert.equal(failure({ ...base, mode: 'both' }), 'Choose whether to convert tension to pitch or pitch to tension.');
assert.equal(failure({ ...base, unit: 'ft' }), 'Choose the diameter unit from in, cm or mm.');
near(C.analyze({ ...base, diameter: '14,0' }).diameter, 14, 'a comma is a decimal mark');
near(C.analyze({ ...base, diameter: '+14' }).diameter, 14, 'a leading plus is accepted');
near(C.analyze({ ...base, diameter: ' 14 ' }).diameter, 14, 'surrounding spaces are ignored');

// ---- The independent Python fixture: 37 heads across sizes, units and modes.
const fixture = JSON.parse(fs.readFileSync(path.join(root, 'tests/fixtures/drumhead_vectors.json'), 'utf8'));
assert.ok(fixture.vectors.length >= 35, 'fixture size');
assert.equal(fixture.cases.length, 22, 'fixture carries the catalog cases');
near(C.ALPHA.m01, fixture.alpha.m01, 'the page uses the reference zero of J0', 1e-12);

const compare = (label, actual, expected) => {
  if (expected === null || typeof expected === 'string' || typeof expected === 'boolean') {
    assert.equal(actual, expected, label);
    return;
  }
  if (typeof expected === 'number') {
    near(actual, expected, label);
    return;
  }
  if (Array.isArray(expected)) {
    assert.equal(actual.length, expected.length, label + ' length');
    expected.forEach((value, index) => compare(label + '[' + index + ']', actual[index], value));
    return;
  }
  for (const [key, value] of Object.entries(expected)) compare(label + ' ' + key, actual[key], value);
};

for (const vector of fixture.vectors) {
  const result = C.analyze(vector.input);
  compare(vector.name, result, vector.expected);
  assert.ok(Math.abs(result.note.cents) <= 50, vector.name + ': cents outside the nearest-note window');
}

// ---- The catalog cases, replayed through the documented input shape.
const catalog = JSON.parse(fs.readFileSync(path.join(root, 'frontend/assets/tool-catalog.json'), 'utf8'));
const matches = catalog.tools.filter((tool) => tool.slug === slug);
assert.equal(matches.length, 1, 'slug must exist exactly once');
const entry = matches[0];
assert.equal(entry.name, 'Drumhead Tuning Calculator');
assert.equal(entry.category, 'Music');
assert.equal(entry.subcategory, 'Estimation & calculation');
assert.equal(entry.risk, 'low');
assert.equal(entry.maturity, 'draft');
assert.equal(entry.reviewedAt, null);
assert.equal(entry.listed, true);
assert.equal(entry.legacyCategory, null);
assert.equal(entry.icon, '\u{1F941}');
assert.equal(new Set(entry.tags).size, entry.tags.length, 'duplicate tags');
assert.equal(new Set(entry.aliases).size, entry.aliases.length, 'duplicate aliases');
assert.ok(entry.method.length > 800, 'method must document the model, the limits and the idealisation');
assert.equal(entry.sources.length, 2);
assert.ok(entry.sources[0].url.startsWith('https://en.wikipedia.org/wiki/Vibration_of_a_circular_membrane'), 'membrane source url');
assert.ok(entry.sources[1].url.startsWith('https://en.wikipedia.org/wiki/Bessel_function'), 'Bessel source url');
assert.equal(entry.testCases.length, 22, 'catalog case count');
assert.equal(entry.testCases.filter((testCase) => testCase.kind === 'golden').length, 7);
assert.equal(entry.testCases.filter((testCase) => testCase.kind === 'boundary').length, 4);
assert.equal(entry.testCases.filter((testCase) => testCase.kind === 'validation').length, 11);
assert.deepEqual(entry.testCases, fixture.cases, 'the catalog cases are the fixture cases');

for (const testCase of entry.testCases) {
  if (testCase.kind === 'validation' || testCase.expectedError) {
    assert.equal(failure(testCase.input), testCase.expectedError, testCase.name);
    continue;
  }
  compare(testCase.name, C.analyze(testCase.input), testCase.expected);
}

// ---- Identities that follow from the wave equation.
const r = C.analyze(base);
near(r.frequency, C.ALPHA.m01 * r.waveSpeed / (2 * Math.PI * r.radius), 'f = alpha c / 2 pi a', 1e-12);
near(r.waveSpeed, Math.sqrt(r.tension / (r.density / 1000)), 'c = sqrt(T / sigma)', 1e-12);
near(r.rimForce, r.tension * Math.PI * r.diameterMm / 1000, 'the rim force is tension times circumference', 1e-12);
near(r.diameterMm, 355.6, 'fourteen inches in millimetres', 1e-12);
assert.equal(r.tensionFromPitch, false);

// Pitch is inversely proportional to the radius at fixed tension and film.
const twelve = C.analyze({ ...base, diameter: '12' });
const twentyFour = C.analyze({ ...base, diameter: '24' });
near(twelve.frequency / twentyFour.frequency, 2, 'half the diameter doubles the pitch', 1e-12);
near(twelve.frequency * twelve.radius, r.frequency * r.radius, 'frequency times radius is constant at fixed tension');

// Pitch follows the square root of the tension.
const doubled = C.analyze({ ...base, tension: '4000' });
near(doubled.frequency / r.frequency, Math.SQRT2, 'double the tension lifts the pitch by a factor of root two', 1e-12);

// The overtone ladder is the Bessel-zero ladder.
near(r.modes.m11 / r.modes.m01, C.ALPHA.m11 / C.ALPHA.m01, 'mode (1,1) ratio', 1e-12);
near(r.modes.m21 / r.modes.m01, C.ALPHA.m21 / C.ALPHA.m01, 'mode (2,1) ratio', 1e-12);
near(r.modes.m02 / r.modes.m01, C.ALPHA.m02 / C.ALPHA.m01, 'mode (0,2) ratio', 1e-12);
assert.ok(r.modes.m01 < r.modes.m11 && r.modes.m11 < r.modes.m21 && r.modes.m21 < r.modes.m02,
  'the modes come out in order');

// Units agree: the same physical head entered three ways.
const inches = C.analyze({ ...base, unit: 'in', diameter: '14' });
const millimetres = C.analyze({ ...base, unit: 'mm', diameter: '355.6' });
const centimetres = C.analyze({ ...base, unit: 'cm', diameter: '35.56' });
near(millimetres.frequency, inches.frequency, 'millimetres agree with inches', 1e-12);
near(centimetres.frequency, inches.frequency, 'centimetres agree with inches', 1e-12);

// Pitch to tension inverts exactly.
const target = C.analyze({ mode: 'pitch', unit: 'in', diameter: '14', density: '356', frequency: '220' });
assert.equal(target.tensionFromPitch, true);
near(target.frequency, 220, 'the target pitch is the pitch', 1e-12);
near(target.modes.m01, 220, 'the fundamental is the target pitch', 1e-12);
const backAgain = C.analyze({ ...base, tension: String(target.tension) });
near(backAgain.frequency, 220, 'tension to pitch inverts pitch to tension', 1e-9);

// A pitch on a note name boundary: 440 Hz is A4 with no cents.
const a4 = C.analyze({ mode: 'pitch', unit: 'in', diameter: '10', density: '249', frequency: '440' });
assert.equal(a4.note.name, 'A4');
near(a4.note.cents, 0, 'A4 is exactly A4', 1e-9);
assert.equal(a4.note.midi, 69);

// The nearest note is always within half a semitone and the octave numbering is right.
for (const frequency of [110, 261.63, 440, 1000, 4000, 12000]) {
  const note = C.analyze({ mode: 'pitch', unit: 'in', diameter: '2', density: '50', frequency: String(frequency) }).note;
  assert.ok(Math.abs(note.cents) <= 50, frequency + ' Hz is within half a semitone of its nearest note');
  assert.equal(note.midi, Math.round(note.midi), 'the midi number is an integer');
}
assert.equal(C.analyze({ mode: 'pitch', unit: 'in', diameter: '10', density: '249', frequency: '261.63' }).note.name, 'C4');

// The heaviest film sounds lower at the same tension.
const heavy = C.analyze({ ...base, density: '498' });
assert.ok(heavy.frequency < r.frequency, 'a heavier head sounds lower at the same tension');
near(heavy.frequency * Math.sqrt(498 / 356), r.frequency, 'pitch scales as one over the square root of areal density', 1e-12);

// A pitch no head can carry is refused rather than reported.
assert.equal(failure({ mode: 'pitch', unit: 'in', diameter: '2', density: '50', frequency: '20000' }),
  'That pitch needs more than 50,000 N/m of tension, which is beyond a drumhead.');
assert.ok(C.analyze({ mode: 'pitch', unit: 'in', diameter: '2', density: '50', frequency: '15000' }).tension < 50000,
  'the highest audible pitch a small head can carry is still under the limit');

// ---- Page contract: shared shell, accessible controls, no runtime foreign APIs.
assert.ok(!/fetch\(|XMLHttpRequest|localStorage|sessionStorage|indexedDB|WebSocket/.test(html), 'network or storage API found');
assert.ok(!/<script[^>]+src="https?:/i.test(html), 'remote script');
assert.ok(!/<link[^>]+href="https?:/i.test(html), 'remote stylesheet');
assert.ok(!/on(?:click|input|change|submit)=/i.test(html), 'inline handler');
assert.ok(!/\beval\s*\(|new\s+Function\b/.test(html), 'unsafe script evaluation');
assert.ok(html.includes('<form id="drum-form" novalidate>'), 'form missing');
assert.ok(html.includes('type="submit"'), 'submit missing');
assert.ok(html.includes('role="alert"'), 'error announcement missing');
assert.ok(html.includes('aria-live="polite" aria-atomic="true"'), 'result region missing');
assert.ok(html.includes('/assets/app.js') && html.includes('/assets/style.css'), 'shared shell assets missing');
for (const id of ['mode', 'diameter', 'unit', 'density', 'tension', 'frequency']) {
  assert.ok(html.includes('for="' + id + '"'), 'missing label for ' + id);
  assert.ok(html.includes('id="' + id + '"'), 'missing control ' + id);
}
for (const id of ['drum-form', 'drum-err', 'drum-out', 'note', 'reset', 'submit', 'tension-field', 'frequency-field']) {
  assert.ok(html.includes('id="' + id + '"'), 'missing id ' + id);
}
assert.ok(html.includes('min-height:44px'), 'controls must stay at a 44 px touch target');
assert.ok(/@media \(max-width:360px\)/.test(html), 'small-screen rule missing');
assert.ok(!/style="[^"]*width:\s*\d{3,}px/.test(html), 'fixed wide inline styles');

const publicCount = catalog.tools.filter((tool) => tool.listed).length;
assert.ok(publicCount >= 2067, 'the catalog keeps growing: ' + publicCount);
assert.equal(catalog.tools.filter((tool) => tool.category === 'Music').length, 52, 'Music count');

console.log('drumhead-tuning: 22 catalog cases, ' + fixture.vectors.length +
  ' reference vectors, identities and page contracts passed');
